async function setGuide(text,filename){activeGuide={name:filename,text,sha256:null};$('guide').textContent=text;$('guideStatus').textContent=text?filename+' · Reference loaded. Custom prose rules require editorial review.':'No guide loaded. You can still explicitly enable the em-dash check.';invalidate('Writing guide changed. Review again to update style findings.');const current=activeGuide;try{const h=await hash(encode(text));if(activeGuide===current)activeGuide.sha256=h;}catch{}}
$('guideFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1024*1024||!/\.(txt|md|markdown)$/i.test(f.name))throw Error('Choose a UTF-8 text or Markdown guide up to 1 MB.');const t=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());if(!t.trim())throw Error('The guide is empty.');await setGuide(t,f.name);}catch(err){$('guideStatus').textContent='Guide not replaced: '+err.message;}e.target.value='';};
