function card(f,technical){const box=element('div',undefined,'finding');const label=element('label'),input=document.createElement('input');input.type='checkbox';input.checked=selected.has(f.id);input.disabled=technical?f.replacement===null:f.after===null;input.setAttribute('aria-label','Select '+(technical?f.codepoint+' at line '+f.line+', column '+f.column:f.title));input.onchange=()=>{input.checked?selected.add(f.id):selected.delete(f.id);update();};label.append(input);const body=element('div');body.append(element('strong',technical?`${f.name} · line ${f.line}, column ${f.column}`:f.title));body.append(element('p',technical?f.reason:f.reason,'small'));body.append(element('span',input.disabled?'Information only':'Suggested change','state'));const context=technical?f.context:f.before;body.append(element('p',context,'quote'));if(!technical&&f.after!==null)body.append(element('p',f.after||'[Remove this passage]','quote'));const locate=element('button','Show in document');locate.onclick=()=>goTo(f.offset,f.end);body.append(locate);if(technical){const tag=element('span','Browser check','source-tag');tag.dataset.codepoint=f.codepoint;body.append(tag);}label.append(body);box.append(label);return box;}
function renderFindings(){$('technical').replaceChildren(...findings.map(f=>card(f,true)));if(states.characters==='Complete'&&!findings.length)$('technical').append(element('p','No unusual characters found in the scanned categories.','empty'));for(const f of styleFindings)$('style').append(card(f,false));if(states.style==='Complete'&&!styleFindings.length)$('style').append(element('p','No findings for the style checks that ran.','empty'));}
